-- Music Land 2026-11-18: ช่องสวมใส่ใหม่ แว่นตา (12 แบบ ดรอปจากมินิบอส/บอส MVP) + พาหนะ (สกู๊ตเตอร์ 3 คัน All Status +20 ดรอปจากบอส MVP)
-- Paste into Supabase > SQL Editor and press Run. Safe to run again.
-- Drops are added to each boss's list (nothing else in the list is touched).

-- 1) the two new equipment types
alter table public.item_defs drop constraint if exists item_defs_type_check;
alter table public.item_defs add constraint item_defs_type_check
  check (type in ('consumable', 'loot', 'card', 'weapon', 'armor', 'head', 'accessory', 'shoes', 'earring', 'glasses', 'mount'));

-- 2) every database function that lists the equipment types (equip, bag, storage, trade, shops...) learns the new ones,
--    and head cards fit glasses like they fit headphones. Patches the functions as they are in your database now.
do $$
declare f record; def text; n int := 0;
begin
  for f in select p.oid from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
    where ns.nspname = 'public' and p.prokind = 'f'
      and (p.prosrc like '%''accessory'', ''shoes'', ''earring'')%' or p.prosrc like '%ei.type = ''earring'')%')
  loop
    def := pg_get_functiondef(f.oid);
    def := replace(def, '''accessory'', ''shoes'', ''earring'')', '''accessory'', ''shoes'', ''earring'', ''glasses'', ''mount'')');
    def := replace(def, 'ei.type = ''earring'')', 'ei.type in (''earring'', ''glasses''))');
    execute def;
    n := n + 1;
  end loop;
  raise notice 'อัปเดตฟังก์ชัน % ตัว', n;
end $$;

